```latex
\section{Background}
\label{subsec:basicDefs}

For the decremental input graph $G$, we let $m$ denote the cardinality of the initial edge set, i.e. the edge set of $G$ at stage $0$, and $n$ refer to the cardinality of its vertex set.

We henceforth denote by $G^*$ the decremental graph $G$ where edge deletions resulting in an increased number of connected components in $G$ are skipped. Therefore $G^*$ is fully-connected at every stage.

We let $\dist[H]{u,v}$ denote the shortest path distance from $u$ to $v$ in graph $H$ and let $\pi_{u,v}$ denote a shortest path between $u$ and $v$ (or some consistently chosen shortest path if there are more than a single one).

We further define for any vertex $v \in V$ in the decremental graph ${G}$, the ball 
\[
B_G(v, r) = \{u \in V | \dist[G]{u,v} \leq r\},
\]
where we drop the subscript when the context is clear. We let $\mathbf{deg}(B_{G^*}(v,r))$ denote the number of edges with both endpoints in the set $B_{G^*}(v,r)$.

\begin{definition}
\label{def:heavy}
For any $\mu > 0$, we say a vertex $v \in V$ is $(\mu, r)$-\textit{heavy} if $\mathbf{deg}(B_{G^*}(v,r)) > \mu$, otherwise we say $v$ is $(\mu, r)$-\textit{light}. 
\end{definition}

\begin{lemma}[c.f.  \cite{bernstein2017deterministic}]
\label{lma:maintainBalls}
For any vertex $s \in V$, we can maintain a data structure on a decremental graph $G^*$ that can report when $s$ transitions from $(\mu, r)$-\textit{heavy} to $(\mu, r)$-\textit{light} and once $s$ is $(\mu, r)$-\textit{light} support the following operations:
\begin{itemize}
    \item It can report when a vertex $w \in B(s,r)$ has increased its distance and be queried for any distance $\mathbf{dist}(s,w)$ for $w \in V$.
    \item Initially given a partition $\mathcal{P}$ of $[0,r]$, it can maintain for each set $P \in \mathcal{P}$ the set of vertices at one of the distance in $P$, i.e. the set
    \[
        V(P) = \{ \mathbf{dist}(s,v) \in P | v \in V\}
    \]
    and report any changes to $P$.
    \item It can support updates to \textit{mark} or \textit{unmark} vertices in $B(s,r)$ and support queries on whether there is a marked vertex in $B(s,r)$.
\end{itemize}
For $\Delta$ updates and queries to the data structure, the total time for updates, queries and reporting changes is $O(\mu r + \Delta)$. Further, the data structure can return a shortest path $\pi_{s,t}$ for any $t \in B(s,r)$ in $O(|\pi_{s,t}|)$ time. Observe that $\pi_{s,t}$ is a shortest path in $G^*$. 
\end{lemma}

\subsection{Overview and Techniques}
\label{sec:overview}

Therefore, we maintain a hierarchy with levels $0, 1, .. , k = \lfloor \sqrt{\log n} \rfloor$ levels.

\section{A layered graph cover}
\label{sec:cover}

\begin{definition}
\label{def:coverSimple}
We call $C \subseteq V$ a $\tau$-cover of $G^
*$, where $\tau \geq 2$, if for every vertex $v \in V$, at any stage, $\min_{c \in C} \mathbf{dist}_G(v, c) \leq \tau$ and let $p_C(v)$ be a vertex $c \in C$ at distance at most $\tau$ to $v$.

We call a collection $\mathcal{C} = \{C_0, C_1, .., C_{\lfloor\log_{\tau} n\rfloor}\}$ a layered $\tau$-cover, if $C_j$ for every $j \in [0, \lfloor\log_{\tau} n\rfloor]$, is a $\tau^j$-cover. 
\end{definition}

Consider the following simple greedy algorithm to maintain a layered $\tau$-cover: We initially let $C_0 = V$. Then for any $j$, we say a vertex $v \in C_{j}$ is $(j+1)$-\textit{eligible} if no other vertex in $B(v, \tau^{j})$ is already in $C_{j}$.

While there is a vertex $v$ that is $(j+1)$-eligible at any point of the algorithm, we add it to $C_{j+1}$ and then check whether any other vertex is still $(j+1)$-eligible. We break ties arbitrarily when processing $(j+1)$-eligible vertices. We use ES-trees as described in lemma \ref{lma:maintainBalls} with $\mu = m$, from each vertex $c$ added to $C_j$ to depth $\tau^j$ and mark the vertices in $B(c, \tau^j)$ that are already in $C_{j+1}$. Then, if the number of marked vertices in the ES-tree is zero, the vertex $c$ is $(j+1)$-eligible.

\begin{definition}
\label{def:cover}
We call $C \subseteq V$ a $(\mu, \tau)$-cover of $G^
*$, where $\tau \geq 2$ if for any $(\mu, 2\tau)$-\textit{light} vertex $v \in V$ there is a $c \in C$ such that $\mathbf{dist}(v,c) \leq \tau$. We call the collection $\mathcal{C}= \{C_0, C_1, .., C_{\lfloor\log_{\tau}(n)\rfloor}\}$ a \textit{layered $(\mu , \tau)$-cover} if each $C_j \in \mathcal{C}$ is a $(\mu, \tau^j)$-cover. Again, we denote by $p_{C_j}(v)$ some arbitrary vertex in $C_j$ that is at distance at most $\tau^j$ from $v$ and let $p_{C_j}(v) = \bot$ if no such vertex exists.
\end{definition}

Throughout the rest of the paper, we let $\mathcal{C}_{\mu} = \{C_{\mu, 0}, C_{\mu, 1}, .., C_{\mu, \lfloor\lg n\rfloor}\}$ denote a specific instance of a layered $(\mu, 2)$-cover.

\section{The Threshold Emulator}
\label{sec:emulator}

\subsection{Detecting Dense Subgraphs}
\label{subsec:detectsubgraphs}

\begin{definition}
\label{def:nearheavy}
For every vertex $v \in V$, we say that $v$ is $(\mu, r, \tau)$-\textit{near-light} at stage $j$, if at any stage $j' \leq j$, $p_{C_{\mu, \tau}}(v) \neq \bot$ and $p_C(v)$ was $(\mu, r + 2\tau)$-\textit{light}. Otherwise, we say that $v$ is $(\mu, r, \tau)$-\textit{near-heavy}.
\end{definition}

To gain some intuition for this definition, let us denote by $\textsc{Near-Heavy}(\mu, r, \tau)$ the set of all $(\mu, r, \tau)$-\textit{near-heavy} vertices in $G^*$ (recall that we defined the set $\textsc{Heavy}(\mu, r)$ quite similarly)

\subsection{Efficient Clustering in Sparse Subgraphs}
\label{subsec:efficientclustering}

\begin{definition}
\label{def:coreCluster}
For any $v \in C_{\mu, r}$, at level $i = \textsc{ClusterLevel}_{\mu, \tau}(c)$, let us define the sets $\textsc{Cluster}_{\mu, \tau}(c)$ to be the set of vertices in the ball $B_{G^*}(c, \tau(1/\epsilon)^{i+1})$, and $\textsc{Core}_{\mu, \tau}(c)$ to be the set of vertices in the ball $B_{G^*}(c, \tau(1/\epsilon)^{i})$.
\end{definition}

\begin{claim}
\label{clm:maintainlevels}
We can maintain for any $(\mu, \tau(1/\epsilon)^{k+1})$-\textit{light} vertex $c \in C_{\mu, \tau}$ an index $i = \textsc{ClusterLevel}_{\mu, \tau}(c) \in [0, k]$ with the following properties:
\begin{enumerate}
    \item $\textsc{ClusterLevel}_{\mu, \tau}(c)$ is monotonically decreasing over time, and
    \item $n^{i/k} \leq |\textsc{Core}_{\mu, \tau}(c)| \leq  |\textsc{Cluster}_{\mu, \tau}(c)| \leq n^{(i+1)/k}$. \label{prop:sparse}
\end{enumerate}
over all stages in $O(\mu \tau(1/\epsilon)^{k+1})$ time.
\end{claim}

Let us now restate the algorithm to select the centers of our hierarchy and analyze it more formally: for each level $i \in [0,k]$, we maintain a set of \textit{active} centers $A_i$ that is a subset of the vertices in $C_{\mu, \tau}$ at cluster level $i$ such that no two vertices in $A_i$ are at distance less than $2\tau(1/\epsilon)^{i}$. In particular, the balls $B_{G^*}(c, \tau(1/\epsilon)^{i})$ for all $c \in A_i$ are pairwise disjoint.

\begin{definition}
Given the dynamic sets $A_0, A_1, .., A_k$ as described above, we define the weighted emulator $H^s_{\mu, \tau, \epsilon}$ such that:
\begin{itemize}
    \item each vertex $v \in V(H^s_{\mu, \tau, \epsilon})$ corresponds to a vertex in $V$ or a connected component in $G^*[\textsc{Near-Heavy}(\mu, 4\tau(1/\epsilon)^{k+1}, \tau)]$ (we call these vertices the \textit{component} vertices), and
    \item for every component vertex $c \in V(H^s_{\mu, \tau, \epsilon})$ corresponding to a connected component we have the edge $(c, v)$ for any $v \in V$ in $E(H^s_{\mu, \tau, \epsilon})$, and
    \item for every center $c \in A_i$, and $v \in \textsc{Cluster}_{\mu,\tau}(c)$ we have an edge $(c, v)$ to  $E(H^s_{\mu, \tau, \epsilon})$, and
    \item $E(H^s_{\mu, \tau, \epsilon})$ contains all edges $\{s\} \times B_{G^*}(s, 2\tau(1/\epsilon)^{k+1})$ that is to the vertices close to $s$.
\end{itemize}
We let the edge weights correspond to the distance between the endpoints in $G^*$ rounded up to the nearest multiple of $\epsilon\tau$, except for the edges incident to component vertices which are maintained with edge weight $\epsilon\tau$.
\end{definition}

\section{Maintaining Distances using the Emulator}
\label{sec:usingEmulator}

To simplify presentation, we assume henceforth that $1/\epsilon$ and $\frac{m}{\mu}$ are integer. Further, we focus in this section on a specific scale of distances that we want to maintain, say we want to find estimates for the distances $\mathbf{dist}_{G^*}(u,v) \in [2^j, 2^{j+1})$ for some integer $\lg \frac{m}{\epsilon^{k+5} \mu} \leq j < \lg n$. We then use lemma \ref{lma:maintainEmu} to obtain an emulator $H^s_{\mu, \tau_j, \epsilon}$ where we set $\tau_j = \frac{\mu 2^j \epsilon^{k+4}}{m}$ (our restriction on $j$ implies that $\epsilon\tau_j$ is an integer). Further, we use the sets $A_0, A_1, .. , A_k$ used to maintain the emulator explicitly. Let us now state a definition of our data structure.

\begin{definition}
\label{def:almostMES}
Let an \textit{almost}-MES-tree $\mathcal{E}_j$ be a data structure that given a source $s \in V$, a depth $d > 0$, the sets $A_0, A_1, .. , A_k$ and $H^s_{\mu, \tau_j, \epsilon}$ maintains a distance estimate $\hat{l}(v)$ for every vertex $v \in V$ as follows:
\begin{itemize}
    \item Each distance estimate $\hat{l}(v)$ is initialized to the distance from $s$ to $v$ in the initial graph $H^s_{\mu, \tau_j, \epsilon}$. 
    \item If a distance estimate $\hat{l}(v)$ is at any stage increased beyond $d$, the vertex $v$ is removed from $\mathcal{E}_r$.
    \item If a vertex $v$ transitions from being $(\mu, 4\tau_j(1/\epsilon)^{k+1}, \tau_j)$-\textit{near-heavy} to $(\mu, 4\tau_j(1/\epsilon)^{k+1}, \tau_j)$-\textit{near-light}, we decrease $\hat{l}(v)$ by $2\epsilon\tau_j$.
    \item If a center $c$ is added to some $A_i$, $c$ checks each vertex $v \in \textsc{Core}_{\mu, \tau_j}(c)$ and updates its own distance estimate $\hat{l}(c) = \max_{v \in \textsc{Core}_{\mu, \tau_j}(c)} \hat{l}^{OLD}(v) - 8 \tau_j(1/\epsilon)^{i}$ where $\hat{l}^{OLD}(v)$ denotes the distance estimate obtained at the last stage for $v$. (This operation might decrease the distance estimate foiling the monotonicity of the function $\hat{l}$).
    \item Edge updates are handled in batches that correspond to the changes in $H^s_{\mu, \tau_j, \epsilon}$ during one stage. After all level updates due to the previous two operations are completed and edge changes are executed, we \uline{consolidate} all distance estimates according to the rule,
    \[
        \hat{l}^{NEW}(v) = \max\{ \hat{l}(v), \min_{(u,v) \in E(H^s_{\mu, \tau_j, \epsilon})} \hat{l}^{NEW}(u) + w(u,v)\}.
    \]
    Observe that this rule is the same rule as in a regular ES-tree procedure.
    \item After the new estimates are found, for any center $c \in A_i$ with $\hat{l}^{NEW}(v) > \hat{l}(v)$, we update for each vertex $v \in \textsc{Core}_{\mu, \tau_j}(c)$ the distance estimate $\hat{l}^{NEW}(v)$ to value 
    \[
    \max\{\hat{l}^{NEW}(v), \hat{l}^{NEW}(c) - \tau_j(1/\epsilon)^{k+1}\}.
    \]
    We say that $c$ \uline{drags} along the vertices in $\textsc{Core}_{\mu, \tau_j}(c)$. Whilst these updates can be evaluated in arbitrary order, dragging a center $c' \in A_j$ resulting in an estimate increase triggers a re-evaluation of the same procedure on $c'$. We do however not re-evaluate the \uline{consolidation} procedure. Observe that this might trigger a series of updates at the next stage. 
\end{itemize}
\end{definition}

\section{Implementing the almost-MES-tree efficiently}
\label{sec:implementMES}

We let $E_{ALL}$ be the collection of all edges that appear in any version of the dynamic graph $H^s_{\mu, \tau_j, \epsilon}$. Here, we treat edges that were re-inserted as new edges, i.e. if $(u,v)$ appears in a version of the graph, is then removed and re-inserted, both versions appear in $E_{ALL}$. This ensures that there is a one-to-one correspondence between edges in $E_{ALL}$ and edge insertions into $H^s_{\mu, \tau_j, \epsilon}$.

\begin{definition}[c.f.  \cite{bernstein2017deterministic}, Def. 2.5]
A dynamic \emph{assignment} $A : E_{ALL} \rightarrow V(H^s_{\mu, \tau_j, \epsilon})$ is a function that maps each edge $(u,v)$ in $E_{ALL}$ to one of its endpoints $u$ or $v$. Further, $A$ must assign each edge $(u,v)$ to one of its endpoints at the moment when $(u,v)$ enters the edge set and cannot be changed afterwards.
\end{definition}

\begin{lemma}[ \cite{bernstein2017deterministic}, Lemma 2.2]
\label{lma:efficientalmostMES}
Consider an almost-MES-tree $\mathcal{E}_j$ as described in definition \ref{def:almostMES}. Then, given a dynamic assignment $A$, let $\Delta(u,v)$ be the total amount of distance estimate changes of $A(u,v)$ in $\mathcal{E}_j$ whilst $(u,v)$ is in the dynamic graph $H^s_{\mu, \tau_j, \epsilon}$. Then, we can implement the almost-MES-tree $\mathcal{E}_j$ as described in definition \ref{def:almostMES} with total time $O(|E_{ALL}| + \sum_{(u,v) \in E_{ALL}} \Delta(u,v) / \epsilon\tau_j)$ and constant worst-case query time.
\end{lemma}
